insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000012', 'en', 'Luxor day trip: temples and the West Bank', 'A long day by road to Luxor with an Egyptologist guide: Karnak, the Valley of the Kings and lunch by the Nile.', 'A full day: about four hours each way by air-conditioned minibus. In Luxor an Egyptologist guide takes you to Karnak Temple, across the Nile to the Valley of the Kings, and to lunch with a view of the river.
Entrance fees are included for the sites in the itinerary; special tombs cost extra on site.', '05:00 pickup from your hotel
09:00 Karnak Temple
11:30 Valley of the Kings
13:30 lunch by the Nile
15:00 Hatshepsut Temple (outside view)
16:00 drive back
20:00 back at your hotel', 'Transport with air conditioning
Egyptologist guide
Entrance fees for listed sites
Lunch and water', 'Special tombs and photo permits
Tips', 'Passport copy required. Long day: not ideal for children under 6.', 'Pickup from your hotel lobby (Hurghada area included).', false);
insert into experience_translations (experience_id, locale, title, summary, description, itinerary, included, excluded, requirements, meeting_info, reviewed) values ('50000000-0000-0000-0000-000000000012', 'ar', 'رحلة يوم إلى الأقصر: المعابد والبر الغربي', 'يوم طويل بالطريق إلى الأقصر مع مرشد أثري: الكرنك ووادي الملوك وغداء على النيل.', 'يوم كامل: حوالي أربع ساعات في كل اتجاه بميني باص مكيف. في الأقصر يرافقك مرشد أثري إلى معبد الكرنك، ثم تعبر النيل إلى وادي الملوك، وتتناول الغداء بإطلالة على النهر.
رسوم الدخول مشمولة للمواقع المذكورة في البرنامج؛ المقابر الخاصة تُدفع في الموقع.', '05:00 الاستلام من الفندق
09:00 معبد الكرنك
11:30 وادي الملوك
13:30 الغداء على النيل
15:00 معبد حتشبسوت (من الخارج)
16:00 طريق العودة
20:00 الوصول إلى الفندق', 'مواصلات مكيفة
مرشد أثري
رسوم دخول المواقع المذكورة
غداء ومياه', 'المقابر الخاصة وتصاريح التصوير
الإكراميات', 'صورة جواز السفر مطلوبة. يوم طويل: غير مثالي للأطفال أقل من 6 سنوات.', 'الاستلام من استقبال الفندق (منطقة الغردقة مشمولة).', false);
